    struct FixedVersionRunner(&'static str);

    impl CommandRunner for FixedVersionRunner {
        fn run(&self, _program: &str, _args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
            Ok(CommandOutput {
                exit_code: Some(0),
