            Err(CliError::Command(CommandError::IncompatibleVersion { program, .. })) => {
                assert_eq!(program, "git");
            }
            other => panic!("expected CliError::Command(IncompatibleVersion), got: {other:?}"),
        }
    }

    #[test]
