    /// Runs a [`registry_argv::Argv`] built by the pure argv layer. This is
    /// the only place `dispatch_registry` touches [`CommandRunner`] --
    /// everything about *what* to run (program, args, cwd) was already
    /// decided by `registry_argv`.
    fn run_argv(&self, argv: &registry_argv::Argv) -> Result<CommandOutput, GraphError> {
        let args: Vec<&str> = argv.args.iter().map(String::as_str).collect();
        Ok(self.runner.run(&argv.program, &args, &argv.cwd)?)
    }

    fn npm_version_is_published(
        &self,
        package_name: &str,
        version: &Version,
        registry: Option<&str>,
    ) -> Result<bool, GraphError> {
        let spec = format!("{package_name}@{}", version.render());
        let mut args = vec!["view", spec.as_str(), "--json"];
        if let Some(registry) = registry {
            args.extend(["--registry", registry]);
        }
        let output = self
            .runner
            .run_quiet("npm", &args, &self.prepared.root, std::time::Duration::from_secs(300))?;
        if output.success() {
            return Ok(!output.stdout_trimmed().is_empty());
        }
        let details = format!("{}\n{}", output.stdout, output.stderr).to_ascii_lowercase();
        if details.contains("e404")
            || details.contains("etarget")
            || details.contains("no matching version")
            || details.contains("is not in this registry")
        {
            return Ok(false);
        }
        Err(GraphError::ReleaseIntentStale {
            reason: StaleReason::legacy_unclassified(),
        })
    }

